<template>
  <div class="page-license">
    <div class="page-header">
      <h2>{{ t('settings.license.title') }}</h2>
    </div>

    <!-- 当前 License -->
    <el-card v-loading="loadingLicense" class="license-card">
      <template #header>
        <span>{{ t('settings.license.currentLicense') }}</span>
      </template>

      <el-alert
        v-if="license?.error_message"
        :title="license.error_message"
        type="warning"
        :closable="false"
        style="margin-bottom: 16px"
      />

      <el-descriptions :column="2" border>
        <el-descriptions-item :label="t('settings.license.licenseId')">
          {{ license?.license_id || '-' }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.license.edition')">
          <el-tag :type="editionTagType">
            {{ editionText }}
          </el-tag>
        </el-descriptions-item>
        <el-descriptions-item :label="t('common.status')">
          <el-tag :type="license?.is_valid ? 'success' : 'danger'">
            {{ license?.is_valid ? t('settings.license.valid') : t('settings.license.invalid') }}
          </el-tag>
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.license.maxNodes')">
          {{ maxNodesText }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.license.issuedAt')">
          {{ formatDate(license?.issued_at) }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.license.expiresAt')">
          {{ formatDate(license?.expires_at) }}
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.license.boundInstallId')">
          {{ license?.server_install_id || '-' }}
        </el-descriptions-item>
      </el-descriptions>
    </el-card>

    <!-- 功能解锁矩阵 -->
    <el-card v-loading="loadingFeatures" class="features-card">
      <template #header>
        <span>{{ t('settings.license.featureMatrix') }}</span>
      </template>

      <el-table :data="featureRows" border style="width: 100%">
        <el-table-column prop="name" :label="t('settings.license.feature')" min-width="180" />
        <el-table-column prop="value" :label="t('common.status')" min-width="120">
          <template #default="{ row }">
            <el-tag v-if="row.enabled === true" type="success">{{ t('settings.license.unlocked') }}</el-tag>
            <el-tag v-else-if="row.enabled === 'trial'" type="warning">{{ t('settings.license.trial') }}</el-tag>
            <el-tag v-else-if="typeof row.enabled === 'number'" type="primary">
              {{ row.enabled === -1 ? t('settings.license.unlimited') : row.enabled }}
            </el-tag>
            <el-tag v-else type="info">{{ t('settings.license.locked') }}</el-tag>
          </template>
        </el-table-column>
      </el-table>

      <div class="website-hint">
        {{ t('settings.license.websiteHint') }}
        <a href="https://chaosm.io" target="_blank" rel="noopener">chaosm.io</a>
      </div>
    </el-card>

    <!-- 上传 License -->
    <el-card class="upload-card">
      <template #header>
        <span>{{ t('settings.license.uploadLicense') }}</span>
      </template>

      <el-upload
        ref="uploadRef"
        action="#"
        :auto-upload="false"
        :limit="1"
        accept=".json"
        :on-change="handleFileChange"
        :on-remove="handleFileRemove"
      >
        <template #trigger>
          <el-button type="primary">{{ t('settings.license.selectFile') }}</el-button>
        </template>
        <el-button
          class="upload-button"
          type="success"
          :loading="uploading"
          :disabled="!selectedFile"
          @click="handleUpload"
        >
          {{ t('settings.license.uploadAndApply') }}
        </el-button>
        <template #tip>
          <div class="el-upload__tip">{{ t('settings.license.uploadTip') }}</div>
        </template>
      </el-upload>
    </el-card>
  </div>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import type { UploadFile } from 'element-plus'
import { getLicense, getLicenseFeatures, uploadLicense, type LicenseRead } from '@/api/license'
import { showError, showSuccess } from '@/utils/error'

const { t } = useI18n()
const license = ref<LicenseRead | null>(null)
const features = ref<Record<string, boolean | number | string>>({})
const loadingLicense = ref(false)
const loadingFeatures = ref(false)
const uploading = ref(false)
const selectedFile = ref<File | null>(null)

const editionText = computed(() => {
  const map: Record<string, string> = {
    free: t('settings.license.editionFree'),
    professional: t('edition.professional'),
    enterprise: t('edition.enterprise'),
  }
  return map[license.value?.edition || 'free'] || license.value?.edition || t('settings.license.editionFree')
})

const editionTagType = computed(() => {
  const edition = license.value?.edition || 'free'
  if (edition === 'enterprise') return 'success'
  if (edition === 'professional') return 'primary'
  return 'info'
})

const maxNodesText = computed(() => {
  const max = license.value?.max_nodes
  if (max === undefined || max === null) return '-'
  return max < 0 ? t('settings.license.unlimited') : t('settings.license.nodesCount', { n: max })
})

const featureRows = computed(() => {
  const labels: Record<string, string> = {
    basic_monitoring: t('settings.license.features.basic_monitoring'),
    alert_rules: t('settings.license.features.alert_rules'),
    max_nodes: t('settings.license.features.max_nodes'),
    metric_retention_days: t('settings.license.features.metric_retention_days'),
    influxdb: t('settings.license.features.influxdb'),
    ai_heal: t('settings.license.features.ai_heal'),
    remote_execution: t('settings.license.features.remote_execution'),
    bulk_registration: t('settings.license.features.bulk_registration'),
    im_channels: t('settings.license.features.im_channels'),
    multi_user_rbac: t('settings.license.features.multi_user_rbac'),
  }
  return Object.entries(features.value).map(([key, value]) => ({
    key,
    name: labels[key] || key,
    enabled: value,
  }))
})

function formatDate(value: string | null | undefined): string {
  if (!value) return '-'
  try {
    const date = new Date(value)
    return date.toLocaleString('zh-CN')
  } catch {
    return value
  }
}

async function loadLicense() {
  loadingLicense.value = true
  try {
    license.value = await getLicense()
  } catch (error) {
    showError(error, t('settings.license.loadFailed'))
  } finally {
    loadingLicense.value = false
  }
}

async function loadFeatures() {
  loadingFeatures.value = true
  try {
    const result = await getLicenseFeatures()
    features.value = result.features
  } catch (error) {
    showError(error, t('settings.license.loadFeaturesFailed'))
  } finally {
    loadingFeatures.value = false
  }
}

function handleFileChange(uploadFile: UploadFile) {
  selectedFile.value = uploadFile.raw || null
}

function handleFileRemove() {
  selectedFile.value = null
}

async function handleUpload() {
  if (!selectedFile.value) return
  uploading.value = true
  try {
    const result = await uploadLicense(selectedFile.value)
    showSuccess(result.message)
    license.value = result.license
    await loadFeatures()
    selectedFile.value = null
  } catch (error) {
    showError(error, t('settings.license.uploadFailed'))
  } finally {
    uploading.value = false
  }
}

loadLicense()
loadFeatures()
</script>

<style scoped>
.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.page-header h2 {
  margin: 0;
}

.license-card,
.features-card,
.upload-card {
  margin-bottom: 20px;
}

.upload-button {
  margin-left: 12px;
}

.website-hint {
  margin-top: 16px;
  color: var(--el-text-color-secondary);
  font-size: 14px;
}

.website-hint a {
  color: var(--el-color-primary);
  text-decoration: none;
}
</style>
